mapper.select:
SET LOCK_TIMEOUT 10000;
WITH INH AS ( SELECT SPP2_NO, SUM(CASE WHEN SPH2_TYPE = 'IN' THEN SPH2_QTY ELSE 0 END) AS TOTAL_IN, SUM(CASE WHEN SPH2_TYPE = 'OUT' THEN SPH2_QTY ELSE 0 END) AS TOTAL_OUT FROM SPAREHISTORY2 WITH(NOLOCK) GROUP BY SPP2_NO ) SELECT P.SPP2_IDX AS spp2_idx, P.SPP2_NO AS spp2_no, P.SPP2_NAME AS spp2_name, P.SPP2_CATEGORY AS spp2_category, P.SPP2_EQUIPMENT AS spp2_equipment, P.SPP2_UNIT AS spp2_unit, P.SPP2_MIN_STOCK AS spp2_min_stock, P.SPP2_REPLACE_CYCLE AS spp2_replace_cycle, ISNULL(H.TOTAL_IN,0) AS total_in, ISNULL(H.TOTAL_OUT,0) AS total_out, ISNULL(H.TOTAL_IN,0) - ISNULL(H.TOTAL_OUT,0) AS current_stock, CASE WHEN ISNULL(H.TOTAL_IN,0) - ISNULL(H.TOTAL_OUT,0) <= 0 THEN N'재고없음' WHEN ISNULL(H.TOTAL_IN,0) - ISNULL(H.TOTAL_OUT,0) < ISNULL(P.SPP2_MIN_STOCK,0) THEN N'부족' ELSE N'정상' END AS stock_status FROM SPAREPART2 P WITH(NOLOCK) LEFT JOIN INH H ON H.SPP2_NO = P.SPP2_NO
AND P.SPP2_CATEGORY = #{category}
AND (P.SPP2_NO LIKE '%'+#{keyword}+'%' OR P.SPP2_NAME LIKE '%'+#{keyword}+'%')
ORDER BY P.SPP2_NO ASC

mapper.delete:
SET LOCK_TIMEOUT 10000;
DELETE FROM SPAREHISTORY2 WHERE SPP2_NO = #{spp2_no};
DELETE FROM SPAREPART2 WHERE SPP2_NO = #{spp2_no};

mapper.select:
SELECT H.SPH2_IDX AS sph2_idx, H.SPP2_NO AS spp2_no, P.SPP2_NAME AS spp2_name, P.SPP2_CATEGORY AS spp2_category, H.SPH2_TYPE AS sph2_type, H.SPH2_QTY AS sph2_qty, H.SPH2_EQUIPMENT AS sph2_equipment, H.SPH2_WORKDESC AS sph2_workdesc, H.SPH2_USERNAME AS sph2_username, CONVERT(VARCHAR(19), H.SPH2_REG_DATE, 120) AS sph2_reg_date FROM SPAREHISTORY2 H WITH(NOLOCK) LEFT JOIN SPAREPART2 P WITH(NOLOCK) ON P.SPP2_NO = H.SPP2_NO
AND H.SPH2_TYPE = #{type}
AND H.SPH2_REG_DATE >= #{fromDt}
AND H.SPH2_REG_DATE < DATEADD(DAY, 1, #{toDt})
ORDER BY H.SPH2_REG_DATE DESC

SET LOCK_TIMEOUT 10000;
WITH INH AS ( SELECT SPP2_NO, SUM(CASE WHEN SPH2_TYPE = 'IN' THEN SPH2_QTY ELSE 0 END) AS TOTAL_IN, SUM(CASE WHEN SPH2_TYPE = 'OUT' THEN SPH2_QTY ELSE 0 END) AS TOTAL_OUT, SUM(CASE WHEN SPH2_TYPE = 'OUT' THEN -SPH2_QTY ELSE SPH2_QTY END) AS CUR_STOCK FROM SPAREHISTORY2 WITH(NOLOCK) GROUP BY SPP2_NO ) SELECT P.SPP2_IDX AS spp2_idx, P.SPP2_NO AS spp2_no, P.SPP2_NAME AS spp2_name, P.SPP2_CATEGORY AS spp2_category, P.SPP2_UNIT AS spp2_unit, P.SPP2_MIN_STOCK AS spp2_min_stock, P.SPP2_REPLACE_CYCLE AS spp2_replace_cycle, P.SPP2_VENDOR_CODE AS spp2_vendor_code, ISNULL(V.CORP_NAME,'') AS vendor_name, ISNULL(P.SPP2_UNITPRICE,0) AS spp2_unitprice, ISNULL(P.SPP2_AVG_PRICE,0) AS spp2_avg_price, ISNULL(STUFF(( SELECT ', ' + F2.FAC_NAME FROM SPAREPART2_FACILITY SF2 INNER JOIN FACILITY F2 ON F2.FAC_CODE = SF2.FAC_CODE WHERE SF2.SPP2_NO = P.SPP2_NO ORDER BY F2.FAC_CODE FOR XML PATH('') ), 1, 2, ''), '') AS equipment_names, ISNULL(H.TOTAL_IN,0) AS total_in, ISNULL(H.TOTAL_OUT,0) AS total_out, ISNULL(H.CUR_STOCK,0) AS current_stock, CASE WHEN ISNULL(H.CUR_STOCK,0) <= 0 THEN N'재고없음' WHEN ISNULL(H.CUR_STOCK,0) < ISNULL(P.SPP2_MIN_STOCK,0) THEN N'부족' ELSE N'정상' END AS stock_status, ISNULL(H.CUR_STOCK,0) * (CASE WHEN ISNULL(P.SPP2_AVG_PRICE,0) > 0 THEN P.SPP2_AVG_PRICE ELSE ISNULL(P.SPP2_UNITPRICE,0) END) AS stock_amount FROM SPAREPART2 P WITH(NOLOCK) LEFT JOIN INH H ON H.SPP2_NO = P.SPP2_NO LEFT JOIN CORP V WITH(NOLOCK) ON V.CORP_CODE = P.SPP2_VENDOR_CODE
AND P.SPP2_CATEGORY = #{category}
AND (P.SPP2_NO LIKE '%'+#{keyword}+'%' OR P.SPP2_NAME LIKE '%'+#{keyword}+'%' OR V.CORP_NAME LIKE '%'+#{keyword}+'%')
ORDER BY P.SPP2_NO ASC

mapper.delete:
SET LOCK_TIMEOUT 10000;
DELETE FROM SPAREHISTORY2 WHERE SPP2_NO = #{spp2_no};
DELETE FROM SPAREPART2_FACILITY WHERE SPP2_NO = #{spp2_no};
DELETE FROM SPAREPART2 WHERE SPP2_NO = #{spp2_no};

mapper.select:
SELECT H.SPH2_IDX AS sph2_idx, H.SPP2_NO AS spp2_no, P.SPP2_NAME AS spp2_name, P.SPP2_CATEGORY AS spp2_category, H.SPH2_TYPE AS sph2_type, H.SPH2_QTY AS sph2_qty, ISNULL(H.SPH2_UNITPRICE,0) AS sph2_unitprice, CASE WHEN H.SPH2_TYPE = 'IN' THEN ISNULL(H.SPH2_UNITPRICE,0) * H.SPH2_QTY ELSE 0 END AS sph2_amount, H.SPH2_FAC_CODE AS sph2_fac_code, ISNULL(F.FAC_NAME,'') AS fac_name, H.SPH2_WORKDESC AS sph2_workdesc, H.SPH2_USERNAME AS sph2_username, CONVERT(VARCHAR(19), H.SPH2_REG_DATE, 120) AS sph2_reg_date FROM SPAREHISTORY2 H WITH(NOLOCK) LEFT JOIN SPAREPART2 P WITH(NOLOCK) ON P.SPP2_NO = H.SPP2_NO LEFT JOIN FACILITY F WITH(NOLOCK) ON F.FAC_CODE = H.SPH2_FAC_CODE
AND H.SPH2_TYPE = #{type}
AND (P.SPP2_NAME LIKE '%'+#{keyword}+'%' OR P.SPP2_NO LIKE '%'+#{keyword}+'%')
AND H.SPH2_REG_DATE >= #{fromDt}
AND H.SPH2_REG_DATE < DATEADD(DAY, 1, #{toDt})
ORDER BY H.SPH2_REG_DATE DESC
